#[doc = "Sandwich product: [`Dipole`] x [`Scalar`] x rev([`Dipole`]).\n\nThe sandwich product `v x a x rev(v)` applies the transformation\nrepresented by the versor `v` to the operand `a`. For rotors, this\nperforms rotation; for motors, it performs rigid body transformation."]
#[allow(unused_variables)]
impl<T: Float> Sandwich<Scalar<T>> for Dipole<T> {
    type Output = Scalar<T>;
    #[inline]
    fn sandwich(&self, operand: &Scalar<T>) -> Scalar<T> {
        Scalar::new_unchecked(
            self.mx() * operand.s() * self.mx()
                + self.my() * operand.s() * self.my()
                + self.mz() * operand.s() * self.mz()
                - self.pw() * operand.s() * self.pw()
                - self.px() * operand.s() * self.px()
                - self.py() * operand.s() * self.py()
                - self.pz() * operand.s() * self.pz()
                + self.vx() * operand.s() * self.vx()
                + self.vy() * operand.s() * self.vy()
                + self.vz() * operand.s() * self.vz(),
        )
    }
}
