            -(self.pw() * operand.mx() * self.pw()) + self.pw() * operand.vx() * self.py()
                - self.pw() * operand.vy() * self.px()
                + self.px() * operand.mx() * self.px()
                - self.px() * operand.mz() * self.pz()
                - self.px() * operand.vy() * self.pw()
                + self.py() * operand.mx() * self.py()
                + self.py() * operand.my() * self.pz()
                + self.py() * operand.vx() * self.pw()
                - self.pz() * operand.mx() * self.pz()
                + self.pz() * operand.my() * self.py()
