#[allow(unused_variables)]
impl<T: Float> Antisandwich<Pseudoscalar<T>> for Dipole<T> {
    type Output = Pseudoscalar<T>;
    #[inline]
    fn antisandwich(&self, operand: &Pseudoscalar<T>) -> Pseudoscalar<T> {
        Pseudoscalar::new_unchecked(
            -(self.mx() * operand.xyzwu() * self.mx())
                - self.my() * operand.xyzwu() * self.my()
                - self.mz() * operand.xyzwu() * self.mz()
                + self.pw() * operand.xyzwu() * self.pw()
                + self.px() * operand.xyzwu() * self.px()
                + self.py() * operand.xyzwu() * self.py()
                + self.pz() * operand.xyzwu() * self.pz()
                - self.vx() * operand.xyzwu() * self.vx()
                - self.vy() * operand.xyzwu() * self.vy()
                - self.vz() * operand.xyzwu() * self.vz(),
        )
    }
}
