impl<T: Float> InverseSandwich<Scalar<T>> for Motor<T> {
    type Output = Scalar<T>;
    #[inline]
    fn try_inverse_sandwich(&self, operand: &Scalar<T>) -> Option<Scalar<T>> {
        let norm_sq = <Self as crate::norm::Normed>::norm_squared(self);
        if norm_sq.abs() < T::epsilon() {
            return None;
        }
        let inv_norm_sq = T::one() / norm_sq;
        Some(Scalar::new_unchecked(
            (self.mx() * operand.s() * self.mx()
                + self.my() * operand.s() * self.my()
                + self.mz() * operand.s() * self.mz()
                - self.pw() * operand.s() * self.pw()
                - self.px() * operand.s() * self.px()
                - self.py() * operand.s() * self.py()
                - self.pz() * operand.s() * self.pz()
                + self.s() * operand.s() * self.s()
                - self.sw() * operand.s() * self.sw()
                - self.sx() * operand.s() * self.sx()
                - self.sy() * operand.s() * self.sy()
                - self.sz() * operand.s() * self.sz()
                + self.u() * operand.s() * self.u()
                + self.vx() * operand.s() * self.vx()
                + self.vy() * operand.s() * self.vy()
                + self.vz() * operand.s() * self.vz())
                * inv_norm_sq,
        ))
    }
}
